function getSolutionSlugs() {
  return Object.keys(SOLUTIONS_DATA);
}
function getSolutionData(slug) {
  const data = SOLUTIONS_DATA[slug];
  if (!data) return null;
  const result = { ...data };
  if (!result.faqs) {
    const rawFaqs = solution_faqs_default[slug];
    if (rawFaqs) {
      result.faqs = Object.entries(rawFaqs).map(([title, items]) => ({
        title,
        items: Array.isArray(items) ? items.map((item) => ({ question: item.q, answer: item.a })) : []
      })).filter((cat) => cat.items.length > 0);
    }
  }
  return result;
}
function getAllSolutions() {
  return getSolutionSlugs().map((slug) => getSolutionData(slug));
}

